mapper.select:
WITH BASE_INFO AS( SELECT SHIFT_DATE,FAB,EQP_G,PRODUCT_STATUS,WIP,AVG_SR,SR_TARGET,WIP_PERCENT,TOTAL_AVG_SR,AVG_SAMP_RATIO,TOTAL_AVG_SAMP_RATIO FROM A1_MFG.SR_MONITOR_SUMMARY_INFO WHERE SHIFT_DATE = TO_CHAR(SYSDATE-8.5/24,'YYYYMMDD') ) SELECT FAB,EQP_G,PRODUCT_STATUS,WIP,AVG_SR,SR_TARGET,AVG_SAMP_RATIO,WIP_PERCENT FROM( SELECT FAB,EQP_G,PRODUCT_STATUS,WIP,AVG_SR,AVG_SAMP_RATIO,SR_TARGET,WIP_PERCENT FROM BASE_INFO UNION ALL SELECT DISTINCT FAB,EQP_G,'SR Target'PRODUCT_STATUS,NULL WIP,SR_TARGET AVG_SR,NULL AVG_SAMP_RATIO,SR_TARGET,NULL WIP_PERCENT FROM BASE_INFO UNION ALL SELECT DISTINCT FAB,EQP_G,'ACT SR'PRODUCT_STATUS,NULL WIP,TOTAL_AVG_SR AVG_SR,TOTAL_AVG_SAMP_RATIO AVG_SAMP_RATIO,SR_TARGET,NULL WIP_PERCENT FROM BASE_INFO ) WHERE EQP_G IN (
#{item}
) ORDER BY EQP_G, DECODE(FAB,'N1A1',1,'N1A3',2),DECODE(PRODUCT_STATUS,'Mass production',1,'Risk',2,'Pilot',3,'SR Target',4,'ACT Target',5)
